return {
  ["uqua-uqua-gas-chambers"] = {overview = {"Solve each changing gas-chamber lock using the precise clue and the correct key alone."}, roles = {{id = "everyone", label = "Everyone", tips = {"Have the definite clue recipient call the key immediately and keep other key types off the opener."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"The chamber begins issuing new lock clues every twenty seconds.", "One player receives a definite key clue; another can receive a misleading either-or clue.", "At least six non-GM players must stand in the chamber's checked area to open the door.", "The opener must carry the correct key and none of the other three key types. A wrong attempt summons a jet flame and starts a one-minute reset.", "Success permanently opens that chamber for the expedition's saved completion window and releases guards beyond it."}}}},
  ["uqua-vrex-barxt-qurat-and-guardian-of-destruction"] = {overview = {"Break the Guardian and Barxt's bond while controlling destructive spirits and channelers."}, roles = {{id = "everyone", label = "Everyone", tips = {"Assign Guardian, Barxt and add control separately. Prioritize channelers when they become vulnerable to reduce the periodic healing link."}}}, phases = {{label = "Guardian", trigger = "Opening through 70%", description = "Fight the Guardian until Barxt enters."}, {label = "Destructive spirits", trigger = "Barxt active above 40%", description = "Handle three waves, then clear every spirit to remove protection."}, {label = "Channelers", trigger = "Barxt at 40%", description = "Defeat the newly vulnerable channelers while managing melee resistance."}, {label = "Sever the bond", trigger = "Barxt at 10%", description = "Kill the Guardian first, then finish the spell-resistant Barxt."}}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"At 70% Guardian health, active Barxt enters combat.", "Barxt creates three waves of four destructive spirits at one-minute intervals. After the third, the bosses become protected until the spirits are cleared; spirit deaths also damage Barxt.", "At 40%, Barxt gains strong melee resistance and the two channelers become attackable.", "At 10%, his melee resistance ends and his spell resistances rise.", "Destroy the Guardian before killing Barxt. Finishing Barxt while the Guardian remains causes the failure outcome and denies the normal reward sequence."}}}},
  ["veeshan-phara-dar-and-the-ring-of-scale"] = {overview = {"Defeat the other Ring of Scale dragons to expose Phara Dar, then control her protectors."}, roles = {{id = "everyone", label = "Everyone", tips = {"Secure the other dragons and reserve add control for the larger final protector waves."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"Phara Dar begins protected while any of the five listed dragon templates remain alive.", "Once all five are gone, the dragon check removes her protection.", "At 80%, 60%, 40% and 20% health, she summons two, three, four and five protectors respectively.", "Ten minutes out of combat heals her and removes remaining protectors."}}}},
  ["poeartha-dust-ring-perfected-warder-of-earth"] = {overview = {"Clear the dust temple to release the Triumvirate of Soil and the Perfected Warder of Earth."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Defeat all thirty-two Dust Devotees to activate the three members of the Triumvirate of Soil.", "Defeat the Triumvirate to summon the Warder, or a Dust Follower if the main encounter is on cooldown.", "The Warder randomly uses one of three setups: additional Soil enemies, repeated groups of three to six protectors, or no added wave.", "The boss can clear hate every twelve seconds. Have tanks ready for both a target reset and a new protector group.", "The overall event allows three hours, while the final boss has a fifty-minute hard despawn."}}}},
  ["poeartha-mud-ring-monstrous-mudwalker"] = {overview = {"Break apart the Sludge Lurker repeatedly, then defeat the Filth Gorgers and Monstrous Mudwalker."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Clear the required mudwalkers and seekers to summon the Sludge Lurker.", "Across four successive stages, the lurker breaks into ten muck mudlets at 75%, 60%, 40% and 15%. Kill every mudlet to reform the lurker and continue.", "Finish the lurker sequence and the four Filth Gorgers to summon the Monstrous Mudwalker, or the cooldown replacement.", "The final boss can clear hate, and killing a player or pet creates additional mudlets. Minimize casualties while keeping an add tank available.", "Complete the ring within three hours and the final boss within its fifty-minute appearance window."}}}},
  ["poeartha-mystical-arbitor-of-earth"] = {overview = {"Defeat the Mystical Arbitor after progressing through the Earthen Badlands’ rings."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Prepare before the Arbitor appears: it has a fifty-minute hard despawn timer.", "Every twelve seconds in combat, it has a chance to wipe its hate list. Tanks should watch for a sudden target change and reclaim it quickly.", "After the Arbitor dies, speak with the planar projection for progression credit."}}}},
  ["poeartha-stone-ring-peregrin-rockskull"] = {overview = {"Clear the stone formations, reunite the rubble and defeat six waves of heaps to expose Peregrin Rockskull."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Clear the four required stone-creature families and the fortifications their deaths create.", "Four mounds of rubble appear. Reduce each to 10% so it becomes protected and returns to the temple center.", "When all four mounds assemble, the Rock Monstrosity reforms and becomes attackable. Defeat it to begin Peregrin’s protection phase.", "Six waves of four stone heaps guard the final boss. Clear all six waves to activate Peregrin or the cooldown replacement.", "The final boss can clear hate and has a fifty-minute hard despawn after activation. The entire ring has a three-hour limit."}}}},
  ["poeartha-vine-ring-derugoak-bloodwalker"] = {overview = {"Clear tainted rock beasts and bloodthirsty vegerogs to summon Derugoak Bloodwalker."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Every three tainted rock-beast kills produces a bloodthirsty vegerog. Clearing the last required beast makes the vegerogs attackable.", "Defeat all ten bloodthirsty vegerogs to summon Derugoak, or a bloodsoaked replacement if the main ring is on cooldown.", "Derugoak summons two mangled vegerogs at 75% health and four at 25%. Prepare add tanks before either threshold.", "The boss periodically clears hate. A five-minute break clears his adds and resets his health-stage triggers.", "The ring has a three-hour limit and the final boss a fifty-minute hard despawn."}}}},
  ["veksar-decaying-lord-galuk-drek"] = {overview = {"Keep the group recovered through Galuk Drek's repeating Darkened Decay."}, roles = {{id = "everyone", label = "Everyone", tips = {"Prepare healing for the opening cast and recurring two-minute spell pressure."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"The lord immediately casts Darkened Decay at a random hated target when combat begins.", "The spell repeats on a two-minute timer.", "The script adds no health-triggered phase changes."}}}},
  ["veksar-raging-bloodgill"] = {overview = {"A bloodgill call can bring a raging goblin into an ordinary pull."}, roles = {{id = "everyone", label = "Everyone", tips = {"Keep a spare tank or control available when pushing warriors below sixty percent."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"At 60% health, a warrior or shaman has a ten-percent chance to summon the raging bloodgill if this event is not already active.", "The active-state marker is scoped to the current instance and expires after thirty minutes.", "Killing the raging goblin clears the marker and allows another eligible trigger."}}}},
  ["vexthal-aten-ha-ra-progression-akhevan-warders"] = {overview = {"Clear Vex Thal's warder gates before attempting the proper Aten Ha Ra encounter."}, roles = {{id = "everyone", label = "Everyone", tips = {"Complete the warder progression before approaching Aten's room."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"Kaas Thox Xi Ans Dyek, Diabo Xi Xin Thall, Thall Va Kelun and Va Xi Aten Ha Ra each remove a required warder on death.", "Diabo Xi Va Temariel and Thall Xundraux Diabo remove the shared fourth warder gate.", "The trigger checks every fifteen seconds and summons the proper Aten only when all five required warders are absent.", "While a required warder remains, the trigger selects the dangerous alternate Aten instead."}}}},
  ["vex-thal-stolen-names-diabo-xi-va"] = {overview = {"Follow the named landmarks and the full text countdowns. Finish the current assignment before taking another.", "After an assignment resolves, allow at least 10 seconds of recovery. Scheduled routine pulses wait through assignments and recovery, then restart their full interval."}, roles = {{id = "tank", label = "Tanks", tips = {"Gather the single witness while holding Diabo."}}, {id = "healer", label = "Healers", tips = {"Prepare a heal before the announced testimony."}}, {id = "damage", label = "Damage dealers", tips = {"Assign an interrupt and backup; killing always works."}}, {id = "everyone", label = "Everyone", tips = {"Native cast, target name and status supply the full warning."}}}, phases = {{label = "The Testimony That Cannot Be Heard", trigger = "Every 42 seconds", description = "One 40000 HP Silencing Witness channels 12 seconds; boss melee pauses. The channel is interruptible."}, {label = "A Silence With Weight", trigger = "Below 35% health", description = "Witness cadence becomes 30 seconds, measured after prior resolution. One witness maximum; routine pulses pause during assignments and 10 second recovery."}, {label = "Routine pressure and support", trigger = "Throughout the encounter", description = "Routine pulse: 500 base magic damage, three-second cast every 30 seconds; first after full interval. Cancel/defer through major warnings/impacts and ten-second recovery, then restart full interval; no catch-up. Shared supports: level 62, AC 400, ATK 150, melee 100-300 every three seconds, 0% slow mitigation, ordinary root/mez/stun/slow. No-melee actors and named melee overrides below replace this range. Protected fixed landmarks:1 HP, untargetable, no melee/casts. Silencing Witness 40,000 HP, maximum 1, melee 100-300: Twelve-second interruptible channel then ordinary melee; next witness waits for existing actor; one hard cap. Major threshold attacks queue behind the current assignment. Support deadl